const membershipRewardRuleObject = (
  kind: string,
  properties: Record<string, unknown>,
  required: string[]
) => ({
  type: "object",
  additionalProperties: false,
  required: ["kind", ...required],
  properties: {
    kind: { type: "string", enum: [kind] },
    ...properties,
    scope: membershipRewardScopeOpenApiSchema
  }
});

