    [`${config.API_PREFIX}/orders`]: {
      get: {
        tags: ["Booking"],
        summary: "Paginated Booking order list",
        security: [{ bearerAuth: [] }],
        parameters: [
          {
            name: "dateMode",
            in: "query",
            description:
              "startsWithin (default) matches order starts; overlaps matches startsAt < to and endsAt > from and requires both bounds. Identity scope is unchanged.",
            schema: { type: "string", enum: ["startsWithin", "overlaps"], default: "startsWithin" }
          },
          { name: "page", in: "query", schema: { type: "integer", minimum: 1 } },
          { name: "pageSize", in: "query", schema: { type: "integer", minimum: 1, maximum: 100 } },
          {
            name: "from",
            in: "query",
            description: "Inclusive ISO 8601 booking start timestamp; requires to",
            schema: { type: "string", format: "date-time" }
          },
          {
            name: "to",
            in: "query",
            description:
              "Exclusive ISO 8601 booking start timestamp; requires from; maximum window is 93 days",
            schema: { type: "string", format: "date-time" }
          },
          {
            name: "status",
            in: "query",
            schema: {
              type: "string",
              enum: [
                "pending",
                "confirmed",
                "inService",
                "awaitingCheckout",
                "awaitingPaymentConfirmation",
                "completed",
                "cancelled"
              ]
            }
          }
        ],
        responses: {
          "200": {
            description: "Paginated orders",
            content: {
              "application/json": {
                schema: {
                  type: "object",
                  required: ["code", "message", "data"],
                  properties: {
                    code: { type: "integer", enum: [0] },
                    message: { type: "string", enum: ["success"] },
                    data: {
                      type: "object",
                      required: ["list", "total", "page", "page_size"],
                      properties: {
                        list: {
                          type: "array",
                          items: { $ref: "#/components/schemas/BookingOrder" }
                        },
                        total: { type: "integer" },
                        page: { type: "integer" },
                        page_size: { type: "integer" }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
